      <Modal visible={ask} transparent>
        <View style={styles.sheet}>
          <Text style={styles.q}>Устгах уу?</Text>
          <View style={styles.row}>
            <Pressable nativeID="no" style={styles.no} onPress={() => setAsk(false)}><Text>Болих</Text></Pressable>
            <Pressable nativeID="yes" style={styles.yes} onPress={confirm}><Text style={styles.yesT}>Тийм</Text></Pressable>
          </View>
        </View>
      </Modal>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 20, alignItems: "center", justifyContent: "center" },
  status: { fontSize: 22, fontWeight: "bold" },
  b: { backgroundColor: "#dc2626", padding: 12, borderRadius: 10 }, t: { color: "#fff", fontWeight: "bold" },
  sheet: { margin: 40, backgroundColor: "#fff", padding: 24, borderRadius: 16, gap: 16 }, q: { fontSize: 18, fontWeight: "bold", textAlign: "center" },
  row: { flexDirection: "row", gap: 12, justifyContent: "center" },
  no: { backgroundColor: "#e2e8f0", padding: 12, borderRadius: 8 }, yes: { backgroundColor: "#dc2626", padding: 12, borderRadius: 8 }, yesT: { color: "#fff", fontWeight: "bold" },
